create extension if not exists pgcrypto;
do $$ begin create type public.problem_status as enum('open','reviewing','solutions_proposed','action_in_progress','resolved'); exception when duplicate_object then null; end $$;
do $$ begin create type public.problem_urgency as enum('low','normal','high','urgent'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,bio text,country text,skills text[] not null default '{}',is_volunteer boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.problems(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null check(char_length(title) between 8 and 140),description text not null check(char_length(description) between 30 and 5000),country text not null,city text,category text not null check(category in('Education','Agriculture','Environment','Food','Technology','Employment','Accessibility','Community')),urgency public.problem_urgency not null default 'normal',status public.problem_status not null default 'open',visibility text not null default 'public' check(visibility in('public','private')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.solutions(id uuid primary key default gen_random_uuid(),problem_id uuid not null references public.problems(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 15 and 5000),created_at timestamptz not null default now());
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),problem_id uuid not null references public.problems(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now());
create table if not exists public.volunteer_profiles(user_id uuid primary key references public.profiles(id) on delete cascade,skills text[] not null default '{}',languages text[] not null default '{}',availability text,bio text,created_at timestamptz not null default now());
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,description text,website text,country text,verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.contributions(id uuid primary key default gen_random_uuid(),problem_id uuid not null references public.problems(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,contribution_type text not null check(contribution_type in('research','volunteer','resource','other')),description text not null,created_at timestamptz not null default now());
create table if not exists public.impact_reports(id uuid primary key default gen_random_uuid(),problem_id uuid not null references public.problems(id) on delete cascade,submitted_by uuid not null references public.profiles(id) on delete cascade,outcome text not null,evidence_url text,verification_status text not null default 'unverified' check(verification_status in('unverified','under_review','verified','rejected')),created_at timestamptz not null default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,problem_id uuid references public.problems(id) on delete cascade,solution_id uuid references public.solutions(id) on delete cascade,reason text not null,details text,status text not null default 'pending',created_at timestamptz not null default now(),check(problem_id is not null or solution_id is not null));
create table if not exists public.user_roles(user_id uuid primary key references public.profiles(id) on delete cascade,role text not null check(role in('moderator','admin')));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1)));return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_moderator() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role in('moderator','admin')); $$;
alter table public.profiles enable row level security;alter table public.problems enable row level security;alter table public.solutions enable row level security;alter table public.comments enable row level security;alter table public.volunteer_profiles enable row level security;alter table public.organizations enable row level security;alter table public.contributions enable row level security;alter table public.impact_reports enable row level security;alter table public.reports enable row level security;alter table public.user_roles enable row level security;
drop policy if exists "profiles public read" on public.profiles;create policy "profiles public read" on public.profiles for select using(true);
drop policy if exists "profiles self update" on public.profiles;create policy "profiles self update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists "problems public read" on public.problems;create policy "problems public read" on public.problems for select using(visibility='public' or user_id=auth.uid() or public.is_moderator());
drop policy if exists "problems self insert" on public.problems;create policy "problems self insert" on public.problems for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "problems owner update" on public.problems;create policy "problems owner update" on public.problems for update to authenticated using(user_id=auth.uid() or public.is_moderator()) with check(user_id=auth.uid() or public.is_moderator());
drop policy if exists "problems owner delete" on public.problems;create policy "problems owner delete" on public.problems for delete to authenticated using(user_id=auth.uid() or public.is_moderator());
drop policy if exists "solutions public read" on public.solutions;create policy "solutions public read" on public.solutions for select using(exists(select 1 from public.problems p where p.id=problem_id and p.visibility='public'));
drop policy if exists "solutions self insert" on public.solutions;create policy "solutions self insert" on public.solutions for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.problems p where p.id=problem_id and p.visibility='public'));
drop policy if exists "solutions owner update" on public.solutions;create policy "solutions owner update" on public.solutions for update to authenticated using(user_id=auth.uid() or public.is_moderator()) with check(user_id=auth.uid() or public.is_moderator());
drop policy if exists "solutions owner delete" on public.solutions;create policy "solutions owner delete" on public.solutions for delete to authenticated using(user_id=auth.uid() or public.is_moderator());
drop policy if exists "comments public read" on public.comments;create policy "comments public read" on public.comments for select using(exists(select 1 from public.problems p where p.id=problem_id and p.visibility='public'));
drop policy if exists "comments self insert" on public.comments;create policy "comments self insert" on public.comments for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "volunteer public read" on public.volunteer_profiles;create policy "volunteer public read" on public.volunteer_profiles for select using(true);
drop policy if exists "volunteer self manage" on public.volunteer_profiles;create policy "volunteer self manage" on public.volunteer_profiles for all to authenticated using(user_id=auth.uid() or public.is_moderator()) with check(user_id=auth.uid() or public.is_moderator());
drop policy if exists "organizations public read" on public.organizations;create policy "organizations public read" on public.organizations for select using(true);
drop policy if exists "organization owner manage" on public.organizations;create policy "organization owner manage" on public.organizations for all to authenticated using(owner_id=auth.uid() or public.is_moderator()) with check(owner_id=auth.uid() or public.is_moderator());
drop policy if exists "contributions public read" on public.contributions;create policy "contributions public read" on public.contributions for select using(true);
drop policy if exists "contributions self insert" on public.contributions;create policy "contributions self insert" on public.contributions for insert to authenticated with check(user_id=auth.uid());
drop policy if exists "impact verified read" on public.impact_reports;create policy "impact verified read" on public.impact_reports for select using(verification_status='verified' or submitted_by=auth.uid() or public.is_moderator());
drop policy if exists "impact self insert" on public.impact_reports;create policy "impact self insert" on public.impact_reports for insert to authenticated with check(submitted_by=auth.uid());
drop policy if exists "reports own read" on public.reports;create policy "reports own read" on public.reports for select using(reporter_id=auth.uid() or public.is_moderator());
drop policy if exists "reports self insert" on public.reports;create policy "reports self insert" on public.reports for insert to authenticated with check(reporter_id=auth.uid());
drop policy if exists "roles self read" on public.user_roles;create policy "roles self read" on public.user_roles for select using(user_id=auth.uid());
-- Assign moderator/admin roles manually in SQL editor after reviewing an account's auth UUID.
